#!/usr/bin/env node
// Regenerates resources/js/icon-data.js from the installed @tabler/icons
// tabler-nodes JSON. Run from deps/ui after bumping @tabler/icons:
//   npm run gen:icon-data
//
// Emits globalThis.__tablerChildren = { name: [[tag, {attr: v}, ...], ...] },
// loaded by index.html before main.js. Icon_tabler_data.ml decodes entries
// into the (tag * attrs) assoc lists the renderers consume.
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, resolve } from "node:path";

// @tabler/icons' exports map wildcards every subpath to ./icons/*, so
// locate the installed package on disk by walking up node_modules dirs.
let iconsDir;
for (let dir = import.meta.dirname; ; dir = dirname(dir)) {
  const candidate = resolve(dir, "node_modules/@tabler/icons/package.json");
  if (existsSync(candidate)) {
    iconsDir = dirname(candidate);
    break;
  }
  if (dirname(dir) === dir) throw new Error("@tabler/icons not found");
}
const readNodes = (kind) =>
  JSON.parse(readFileSync(resolve(iconsDir, `tabler-nodes-${kind}.json`), "utf8"));
const outline = readNodes("outline");
const filled = readNodes("filled");

const table = { ...outline };
for (const [name, children] of Object.entries(filled)) {
  table[`${name}-filled`] = children;
}

const out = `// Generated by deps/ui/scripts/gen-icon-data.mjs from
// @tabler/icons tabler-nodes-{outline,filled}.json — do not edit.
globalThis.__tablerChildren=${JSON.stringify(table)};
`;

const dest = resolve(import.meta.dirname, "../../../resources/js/icon-data.js");
writeFileSync(dest, out);
console.log(
  `wrote ${dest}: ${Object.keys(table).length} icons, ${out.length} bytes`,
);
